// TRUST BOUNDARY. Every id is validated here and nowhere else: the two
// Snowflake nodes downstream interpolate the pre-quoted lists this node
// emits, so the regexes below are what make that interpolation
// injection-safe. Error messages name the PROBLEM, never the offending
// value -- mirrors src/pathfinder/action_console/secret_scrub.py.

const MAX_IDS = 10000;
const INT_RE = /^[0-9]+$/;

// Both normalizers LOWERCASE. Snowflake string comparison is case-sensitive,
// so an uppercase-submitted uuid used to be interpolated verbatim and matched
// nothing -- a silent empty result, not an error. Lowercasing also matches
// _canon() in n8n.py, which is what the client keys rows by.
function toDashedUuid(raw) {
  const stripped = String(raw).trim().toLowerCase().replace(/-/g, '');
  if (!/^[0-9a-f]{32}$/.test(stripped)) return null;
  return `${stripped.slice(0,8)}-${stripped.slice(8,12)}-${stripped.slice(12,16)}-${stripped.slice(16,20)}-${stripped.slice(20)}`;
}

function toIterableProUuid(raw) {
  const stripped = String(raw).trim().toLowerCase().replace(/^pro_/, '').replace(/-/g, '');
  if (!/^[0-9a-f]{32}$/.test(stripped)) return null;
  return `pro_${stripped}`;
}

const body = $input.first().json.body || {};
const raw = body.id;
const rawList = Array.isArray(raw) ? raw : [raw];

if (rawList.length === 0 || rawList.some(v => v === undefined || v === null || v === '')) {
  throw new Error('id(s) must be a non-empty value or array of values');
}
// Cap moved here from the old Validate node, which no longer sees the raw
// request. Losing it would let one call fan out unboundedly.
if (rawList.length > MAX_IDS) {
  throw new Error(`at most ${MAX_IDS} ids per request, got ${rawList.length}`);
}

// Deduped per bucket rather than rejected: with three accepted id spaces a
// duplicate is far more likely to be a caller listing the same org twice
// than a bug worth failing the whole batch over. IN () would dedupe anyway.
const uuids = new Set();
const proUuids = new Set();
const ints = new Set();
for (const entry of rawList) {
  const value = String(entry).trim();
  if (/^pro_/i.test(value)) {
    const asProUuid = toIterableProUuid(value);
    if (!asProUuid) throw new Error(`id "${entry}" has a pro_ prefix but isn't a well-formed pro id`);
    proUuids.add(asProUuid);
    continue;
  }
  const asUuid = toDashedUuid(value);
  if (asUuid) { uuids.add(asUuid); continue; }
  if (INT_RE.test(value)) { ints.add(value); continue; }
  throw new Error(`id "${entry}" is neither an org_uuid, a pro_ id, nor an integer org_id`);
}

// Sentinels keep `IN (...)` syntactically valid when a bucket is empty.
const quote = (values, fallback) =>
  (values.size ? [...values] : [fallback]).map(v => `'${v}'`).join(', ');

const uuidList    = quote(uuids, '00000000-0000-0000-0000-000000000000');
const proUuidList = quote(proUuids, 'pro_00000000000000000000000000000000');
const intList     = (ints.size ? [...ints] : ['-1']).join(', ');

return [{ json: { uuid_list: uuidList, pro_uuid_list: proUuidList, int_list: intList } }];

return $input.all().map(item => {
  const { dataFields, ...rest } = item.json;
  return {
    json: {
      org_uuid: $('Router Query').item.json.org_uuid,
      ...rest,       // userId, etc.
      ...dataFields, // Iterable custom fields — Waypoint drops these anyway
      // id echo LAST so Snowflake's value always wins: Waypoint re-keys the
      // brief by pro_uuid, and Iterable's dataFields copy can be stale/absent
      pro_uuid: $('Router Query').item.json.pro_uuid,
    },
  };
});

// Denylist, not allowlist: strips known-PII keys anywhere in the merged
// object (top level and nested, e.g. Iterable's user.dataFields), keeps
// everything else untouched -- Snowflake bands, org_uuid, pro_uuid, and
// any Iterable custom field not named below.
// ponytail: denylist ceiling -- a new PII field on either side leaks
// through silently until someone adds it here. Upgrade to the n8n.py-style
// allowlist if that risk becomes real.
const PII_KEYS = new Set([
  'email', 'emailaddress', 'phone', 'phonenumber', 'mobile_number', 'mobilenumber',
  'first_name', 'firstname', 'last_name', 'lastname', 'name', 'fullname', 'full_name',
  'address', 'street', 'city', 'state', 'zip', 'zipcode', 'postal_code',
  'ip', 'ipaddress', 'ssn', 'dob', 'date_of_birth', 'birthdate',
  'devices', 'useragent', 'lead_id',
]);

function stripPii(value) {
  if (Array.isArray(value)) return value.map(stripPii);
  if (value && typeof value === 'object') {
    const out = {};
    for (const [key, val] of Object.entries(value)) {
      if (PII_KEYS.has(key.toLowerCase())) continue;
      out[key] = stripPii(val);
    }
    return out;
  }
  return value;
}

return $input.all().map(item => ({ json: stripPii(item.json) }));
